INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('9dxw4khjgxlg1tw79dxdd6qsszlrcpxk', '2025-Q2', 'Jun/2025', '2025-06-17T23:39'::timestamptz, 'Nelbia Pricilla de Aguiar Dambroz', 'nelbia pricilla de aguiar dambroz', 'PHARUS', 'Gabriel Oliveira', 2.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Tenho clareza e estou executando com consistência', 'Bom, pelo valor do investimento que é alto, havia uma expectativa maior. Acredito que a estratégia que vocês utilizam acaba se tornando inviável de ter um resultado ao longo de um ano do programa. Tanto pelo retropatrimonio, quanto para revenda de carta contemplada, ficamos refém das oportunidades que nós são dadas apenas pelo assessor. Sendo assim, acredito que muitas possibilidades e oportunidade se perdem.', 'Acesso a oportunidades melhores, que realmente possa chegar no que é proposto no início, construção de renda passiva.', NULL, 'Resultado do método.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', '9dxw4khjgxlg1tw79dxdd6qsszlrcpxk', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.